/*==============================================================*/
/* Table: CHB_REPORT_CHECK                                      */
/*==============================================================*/
create table CHB_REPORT_CHECK 
(
   CHECK_SEQNO          VARCHAR(32) not null,
   REP_CODE             VARCHAR(20),
   REP_NAME             VARCHAR(32),
   VALID_KEY            VARCHAR(1000),
   CHECK_RESULT         VARCHAR(32),
   ERROR_INFO            CLOB,
   WARN_INFO             CLOB,
   ORG_CODE             VARCHAR(20),
   DATA_TIME            TIMESTAMP(6),
   CREATE_DEPT          VARCHAR(32),
   UPDATE_USER          VARCHAR(20),
   UPDATE_TIME          TIMESTAMP(6),
   CREATE_USER          VARCHAR(20),
   CREATE_TIME          TIMESTAMP(6),
   IS_LOGIC_CHECK		VARCHAR(20),
   PRIMARY KEY(CHECK_SEQNO)
);
COMMENT ON TABLE "CHB_REPORT_CHECK" IS '报送前检查';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."CHECK_SEQNO" IS '检查序列号';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."REP_CODE" IS '报表ID';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."REP_NAME" IS '报表名称';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."VALID_KEY" IS '唯一标识';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."CHECK_RESULT" IS '检查结果';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."ERROR_INFO" IS '错误信息项';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."WARN_INFO" IS '警告信息项';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."ORG_CODE" IS '机构代码';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."DATA_TIME" IS '数据日期';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."CREATE_DEPT" IS '创建部门';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."UPDATE_USER" IS '更新人';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."UPDATE_TIME" IS '更新时间';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."CREATE_USER" IS '创建人';
COMMENT ON COLUMN "CHB_REPORT_CHECK"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN CHB_REPORT_CHECK.IS_LOGIC_CHECK IS '是否逻辑校验';

