--新建上游接口文件读取处理监控信息表
-- ----------------------------
-- Table structure for CHB_FILE_READ_MONITOR_INFO
-- ----------------------------
CREATE TABLE CHB_FILE_READ_MONITOR_INFO (
  HANDLE_SEQNO          VARCHAR(32) NOT NULL,
  HANDLE_FILE_NAME             VARCHAR(100) NOT NULL ,
  HANDLE_FILE_PATH             VARCHAR(100) NOT NULL ,
  HANDLE_FILE_TYPE            VARCHAR(10) NOT NULL ,
  FILE_READ_START_TIME     TIMESTAMP NOT NULL ,
  FILE_READ_END_TIME     TIMESTAMP NULL ,
  FILE_DATA_COUNT decimal(20,0),
  FILE_HANDLE_STATUS VARCHAR(10),
  FILE_HANDLE_RESULT_MSG CLOB,
  CREATE_DEPT          VARCHAR(32),
  UPDATE_USER         VARCHAR(20),
  UPDATE_TIME         TIMESTAMP,
  CREATE_USER         VARCHAR(20),
  CREATE_TIME         TIMESTAMP,
  CONSTRAINT PK_CHB_FILE_READ_MONITOR_INFO PRIMARY KEY (HANDLE_SEQNO)
)
;
COMMENT ON TABLE CHB_FILE_READ_MONITOR_INFO IS '上游接口文件读取处理监控信息';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.HANDLE_SEQNO IS '文件处理序列号';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.HANDLE_FILE_NAME IS '数据文件名';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.HANDLE_FILE_PATH IS '数据文件路径';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.HANDLE_FILE_TYPE IS '数据文件类别';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.FILE_READ_START_TIME IS '数据文件读取开始时点';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.FILE_READ_END_TIME IS '数据文件读取结束时点';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.FILE_DATA_COUNT IS '文件数据条数';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.FILE_HANDLE_STATUS IS '文件处理状态';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.FILE_HANDLE_RESULT_MSG IS '文件处理结果说明';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.CREATE_DEPT IS '创建部门';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.UPDATE_USER IS '更新人';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.UPDATE_TIME IS '更新时间';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.CREATE_USER IS '创建人';
COMMENT ON COLUMN CHB_FILE_READ_MONITOR_INFO.CREATE_TIME IS '创建时间';

