--4.重新创建CHB_SUBMIT_STATUS
CREATE TABLE
    CHB_SUBMIT_STATUS
    (
        SEQNO VARCHAR2(20) NOT NULL,
        SUBMIT_NUM VARCHAR2(20),
        SUBMIT_TYPE VARCHAR2(30),
        SUBMIT_FEEDBACK_STATUS VARCHAR2(10),
        UPDATE_USER VARCHAR2(20),
        UPDATE_TIME TIMESTAMP(6),
        CREATE_USER VARCHAR2(32),
        CREATE_TIME TIMESTAMP(6),
        REPORT_NO VARCHAR2(20),
        SUBMIT_FEEDBACK_MSG VARCHAR2(600),
        UNIQUE_IDENTI VARCHAR2(300),
        CREATE_DEPT VARCHAR2(32),
        PRIMARY KEY (SEQNO)
    );
COMMENT ON TABLE CHB_SUBMIT_STATUS
IS
    '报送状态表';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.SEQNO
IS
    '流水号';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.SUBMIT_NUM
IS
    '批次号';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.SUBMIT_TYPE
IS
    '报送类型';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.SUBMIT_FEEDBACK_STATUS
IS
    '报送反馈状态';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.UPDATE_USER
IS
    '更新人';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.UPDATE_TIME
IS
    '更新时间';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.CREATE_USER
IS
    '创建人';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.CREATE_TIME
IS
    '创建时间';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.REPORT_NO
IS
    '报送编码';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.SUBMIT_FEEDBACK_MSG
IS
    '报送反馈消息';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.UNIQUE_IDENTI
IS
    '唯一标识';
COMMENT ON COLUMN CHB_SUBMIT_STATUS.CREATE_DEPT
IS
    '创建部门';
	
