 create or replace view chb_view_equ_sub as (SELECT
            	INDENTIFY_MARK,
            	ORG_INDENTIFY_MARK,
            	REGIST_BANK_CODE,
            	IS_BELONG_BANK,
            	THE_BANK_NAME,
            	THE_BANK_CODE,
            	HOLDER_MARK,
            	HOLDER_REGION,
            	HOLDER_TYPE,
            	PERSONAL_IDENTIFY_TYPE,
            	INSTITUTION_IDENTIFY_TYPE,
            	OTHER_IDENTIFY_NAME,
            	IDENTIFY_NUMBER,
            	SPV_CAP_ACC_BANK,
            	OTHER_CAP_ACC_BANK,
            	SPV_REGIST_CODE,
            	HOLDER_DATE,
            	HOLDER_NAME,
            	HOLDER_SEX,
            	HOLDER_RISK_PREFER,
            	HOLDER_CELLPHONE,
            	HOLDER_TELEPHONE,
            	HOLDER_EMAIL,
            	TYPE,
            	REMARK,
            	SUBMIT_STATUS,
            	SUBMIT_TIME,
            	CHB_SUBMIT_DEADLINE,
            	SUBMIT_DEADLINE,
            	STATUS,
            	DEPT_CODE,
            	UPDATE_USER,
            	UPDATE_TIME,
            	CREATE_USER,
            	CREATE_TIME,
            	SUMIT_SEQ,
            	DELETE_RES,
            	ORG_CODE,
            	CREATE_DEPT,
            	CHECK_SEQNO
        	FROM CHB_EQU_SUB
        	WHERE SUBMIT_STATUS IN ('02','03')
        	UNION ALL
        		SELECT
            	INDENTIFY_MARK,
            	ORG_INDENTIFY_MARK,
            	REGIST_BANK_CODE,
            	IS_BELONG_BANK,
            	THE_BANK_NAME,
            	THE_BANK_CODE,
            	HOLDER_MARK,
            	HOLDER_REGION,
            	HOLDER_TYPE,
            	PERSONAL_IDENTIFY_TYPE,
            	INSTITUTION_IDENTIFY_TYPE,
            	OTHER_IDENTIFY_NAME,
            	IDENTIFY_NUMBER,
            	SPV_CAP_ACC_BANK,
            	OTHER_CAP_ACC_BANK,
            	SPV_REGIST_CODE,
            	HOLDER_DATE,
            	HOLDER_NAME,
            	HOLDER_SEX,
            	HOLDER_RISK_PREFER,
            	HOLDER_CELLPHONE,
            	HOLDER_TELEPHONE,
            	HOLDER_EMAIL,
            	TYPE,
            	REMARK,
            	SUBMIT_STATUS,
            	SUBMIT_TIME,
            	CHB_SUBMIT_DEADLINE,
            	SUBMIT_DEADLINE,
            	STATUS,
            	DEPT_CODE,
            	UPDATE_USER,
            	UPDATE_TIME,
            	CREATE_USER,
            	CREATE_TIME,
            	SUMIT_SEQ,
            	DELETE_RES,
            	ORG_CODE,
            	CREATE_DEPT,
            	CHECK_SEQNO
        	FROM CHB_EQU_SUB_HIS
            WHERE SUBMIT_STATUS IN ('02', '03'));
			
